def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return out
    (r0, c0), (r1, c1) = sorted(markers)
    dr, dc = r0-r1, c0-c1
    # Translate the non-marker pattern in the lower/right region toward the
    # upper marker by the displacement between the two 5 markers.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v and v != 5:
                rr, cc = r+dr, c+dc
                if 0 <= rr < len(grid) and 0 <= cc < len(row) and grid[rr][cc] == 0:
                    out[rr][cc] = v
    return out

